/// <summary>
/// One handheld menu and its lines, in order.
/// </summary>
[DataContractAttribute]
class HSMobileOpsMenuRow
{
    str      menuId;
    str      name;
    List     lines;
}

Method.Source:
[DataMemberAttribute('MenuId')]
public str parmMenuId(str _value = menuId)
{
    menuId = _value;
    return menuId;
}

[DataMemberAttribute('Name')]
public str parmName(str _value = name)
{
    name = _value;
    return name;
}

[DataMemberAttribute('Lines'),
 DataCollectionAttribute(Types::Class, classStr(HSMobileOpsMenuLineRow))]
public List parmLines(List _value = lines)
{
    lines = _value;
    return lines;
}
